delete from content
where node_id in (select node_id from master)
  and not (depth = 'research' and level = 'advanced' and format = 'read');

-- Curated, human-reviewed quiz — same set served at every level.
with q as (
  select $wf_quiz$[
    {"id":"q1","type":"mcq","prompt":"Vilhelm Bjerknes framed weather prediction as an 'initial-value problem.' What two things does that framing say a forecast requires?","options":["A powerful computer and a large staff","An accurate diagnosis of the current state and a way to integrate the governing equations forward in time","A long historical record and a good analog","Satellite data and a human forecaster"],"answerIndex":1,"explanation":"Because the atmosphere obeys known physical laws, a forecast needs (1) an accurate diagnosis of the current state — the initial conditions — and (2) a method to integrate the governing equations forward in time. Everything else in modern forecasting elaborates these two pillars: data assimilation for the state, and the model for the integration."},
    {"id":"q2","type":"mcq","prompt":"Why do the elementary reference methods (persistence, climatology) remain fundamental to modern forecasting?","options":["They are still the most accurate methods available","They define the 'zero of skill' — every skill score is measured relative to them","They require no observations","They work only in the tropics"],"answerIndex":1,"explanation":"A forecasting system that cannot beat persistence or climatology has no value, so skill scores are defined relative to a reference method: skill = 1 − S/S_ref. That is why these humble benchmarks are permanently load-bearing."},
    {"id":"q3","type":"mcq","prompt":"In numerical weather prediction, 'parameterizations' are used to represent:","options":["The large-scale winds resolved by the model grid","Sub-grid processes too small to resolve — radiation, turbulence, cloud microphysics, convection","The observations fed into data assimilation","The statistical post-processing of model output"],"answerIndex":1,"explanation":"A ~10 km grid cell cannot resolve a cloud, an eddy, or a raindrop, yet these control the weather people feel. Parameterizations are physically based statistical models of these unresolved processes — and the true seat of most forecast error. Deep convection is the most consequential (and criticized) such closure."},
    {"id":"q4","type":"mcq","prompt":"The roughly two-week 'predictability horizon' for day-to-day weather arises because:","options":["Computers are not yet fast enough","Satellites cannot observe the whole atmosphere","The atmosphere is chaotic — small initial errors grow and cascade upscale, so no observing system can breach the limit","Models lack enough vertical levels"],"answerIndex":2,"explanation":"Lorenz's sensitive dependence on initial conditions means small, unavoidable initial errors grow exponentially and — crucially — cascade upscale from small scales to large. Halving the initial error buys only a few hours at the wall, so the ~2-week limit is intrinsic, not a technological shortfall."},
    {"id":"q5","type":"open","prompt":"What problem does data assimilation solve, and in one line, what is the variational cost function trading off?","rubric":"Data assimilation produces the model's initial state (the analysis) from observations that are sparse, unevenly distributed, silent over oceans at the surface, individually noisy, and not in dynamical balance — none of which alone can fill every grid point. It solves this by optimally combining the observations with a BACKGROUND (the previous short-range forecast), each weighted by its uncertainty. The variational cost function J(x) trades off two penalties: departure of the analysis from the background (weighted by the background-error covariance B) against misfit to the observations (weighted by the observation-error covariance R, through the observation operator H). Minimizing it is Bayesian (maximum a posteriori) estimation."},
    {"id":"q6","type":"open","prompt":"A single deterministic forecast must eventually be wrong. How does ensemble forecasting turn the chaos limit into something useful, and what does the ensemble spread tell you?","rubric":"Instead of one integration, an ensemble runs many (20–100) forecasts from slightly different initial states (sampling analysis uncertainty) and with perturbed model physics (sampling model uncertainty). The output is a forecast DISTRIBUTION rather than a single value: the ensemble mean (which beats individual members at medium range as unpredictable details average out), and probabilities read from member counts (e.g., 34 of 51 members exceed 20 mm → ~two-thirds chance). The SPREAD estimates the forecast's own uncertainty/expected error — the spread–skill relationship — and it is flow-dependent, so the ensemble says WHEN the atmosphere is predictable and when it faces a genuine fork. (Raw ensembles are usually under-dispersive, which is why post-processing/calibration is needed.)"}
  ]$wf_quiz$::jsonb as questions
)
insert into quizzes (node_id, level, questions, generated)
select 'earth-and-environmental-science/meteorology-and-climate/forecasting', lvl, q.questions, true
from q, (values ('easy'), ('advanced'), ('expert')) as l(lvl)
on conflict (node_id, level) do update
  set questions = excluded.questions, generated = excluded.generated;
